pub fn hasNoMorePendingLifecycleScripts(client: *PackageManager) bool {
        _ = client.reportSlowLifecycleScripts();
        return (client.pending_lifecycle_script_tasks.load(.monotonic) == 0);
}

pub fn tickLifecycleScripts(client: *PackageManager) void {
        _ = client.event_loop.tickOnce(client);
}

pub fn sleep(client: *PackageManager) void {
        _ = client.reportSlowLifecycleScripts();
        _ = Output.flush();
        _ = client.event_loop.tick(client, hasNoMorePendingLifecycleScripts);
}

