                client.last_reported_slow_lifecycle_script_at = current_time;
                const package_name = active_lifecycle_script_running_for_the_longest_amount_of_time.package_name;
                if ((!((package_name.len > 1) and (package_name[@as(usize, @intCast((package_name.len - 1)))] == 115)))) {
                    _ = Output.warn("{s}'s postinstall cost you {f}\n", .{ package_name, bun.fmt.fmtDurationOneDecimal(time_running) });
                } else {
                    _ = Output.warn("{s}' postinstall cost you {f}\n", .{ package_name, bun.fmt.fmtDurationOneDecimal(time_running) });
                }
                _ = Output.flush();
            }
        }
}

pub fn loadRootLifecycleScripts(client: *PackageManager, root_package: Package) void {
        const binding_dot_gyp_path = Path.joinAbsStringZ(Fs.FileSystem.instance.top_level_dir, (&.{ "binding.gyp" }), .auto);
        const buf = client.lockfile.buffers.string_bytes.items;
        const name = (if (@typeInfo(@TypeOf(root_package)) == .@"enum" or @typeInfo(@TypeOf(root_package)) == .@"union") @tagName(root_package) else root_package.name).slice(buf);
        var top_level_dir: bun.AbsPath(.{.sep=.auto}) = .initTopLevelDir();
        _ = &top_level_dir;
        defer {
        _ = top_level_dir.deinit();
        }
        if (root_package.scripts.hasAny()) {
            const add_node_gyp_rebuild_script = ((root_package.scripts.install.isEmpty() and root_package.scripts.preinstall.isEmpty()) and Syscall.exists(binding_dot_gyp_path));
            client.root_lifecycle_scripts = root_package.scripts.createList(client.lockfile, buf, (&top_level_dir), name, .root, add_node_gyp_rebuild_script);
        } else {
            if (Syscall.exists(binding_dot_gyp_path)) {
                client.root_lifecycle_scripts = root_package.scripts.createList(client.lockfile, buf, (&top_level_dir), name, .root, true);
            }
        }
}

pub fn spawnPackageLifecycleScripts(self: *PackageManager, ctx: Command.Context, list: Lockfile.Package.Scripts.List, optional: bool, foreground: bool, install_ctx: ?LifecycleScriptSubprocess.InstallCtx) !void {
        const log_level = self.options.log_level;
        var any_scripts = false;
        _ = &any_scripts;
        for (list.items) |maybe_item| {
            _ = &maybe_item;
            if ((maybe_item != null)) {
                any_scripts = true;
                break;
            }
        }
        if ((!any_scripts)) {
            return;
        }
        _ = try self.ensureTempNodeGypScript();
        const cwd = list.cwd;
        var this_transpiler = try self.configureEnvForScripts(ctx, log_level);
        _ = &this_transpiler;
        var script_env = try this_transpiler.env.map.cloneWithAllocator(bun.default_allocator);
        _ = &script_env;
        defer {
        _ = script_env.map.deinit();
        }
        const original_path = ((script_env.get("PATH")) orelse (""));
        var PATH: bun.EnvPath({}) = try .initCapacity(bun.default_allocator, ((((original_path.len + 1) + "node_modules/.bin".len) + cwd.len) + 1));
        _ = &PATH;
        defer {
        _ = PATH.deinit();
        }
        var parent: ?[]const u8 = cwd;
        _ = &parent;
        while (parent) |dir| {
            var builder = PATH.pathComponentBuilder();
            _ = &builder;
            _ = builder.append(dir);
            _ = builder.append("node_modules/.bin");
            _ = try builder.apply();
            parent = std.fs.path.dirname(dir);
        }
        _ = try PATH.append(original_path);
        _ = try script_env.put("PATH", PATH.slice());
        const envp = try script_env.createNullDelimitedEnvMap(self.allocator);
        const shell_bin = shell_bin: {
        if (comptime Environment.isWindows) {
            break :shell_bin null;
        }
        if (self.env.get("PATH")) |env_path| {
            _ = &env_path;
            break :shell_bin bun.cli.RunCommand.findShell(env_path, cwd);
        }
        break :shell_bin null;
};
        _ = try LifecycleScriptSubprocess.spawnPackageScripts(self, list, envp, shell_bin, optional, log_level, foreground, install_ctx);
}

pub fn findTrustedDependenciesFromUpdateRequests(client: *PackageManager) std.AutoArrayHashMapUnmanaged(TruncatedPackageNameHash,void) {
        const parts = client.lockfile.packages.slice();
        var set: std.AutoArrayHashMapUnmanaged(TruncatedPackageNameHash,void) = .{};
        _ = &set;
        if ((client.options.do.trust_dependencies_from_args and (client.lockfile.packages.len > 0))) {
            const root_deps = parts.items(.dependencies)[@as(usize, @intCast(client.root_package_id.get(client.lockfile, client.workspace_name_hash)))];
            var dep_id = root_deps.off;
            _ = &dep_id;
            const end = (dep_id +| root_deps.len);
            while ((dep_id < end)) : (dep_id = (dep_id + 1)) {
                const root_dep = client.lockfile.buffers.dependencies.items[@as(usize, @intCast(dep_id))];
                for (cp_iter_slice(client.update_requests)) |request| {
                    _ = &request;
                    if (request.matches(root_dep, client.lockfile.buffers.string_bytes.items)) {
                        const package_id = client.lockfile.buffers.resolutions.items[@as(usize, @intCast(dep_id))];
                        if ((package_id == invalid_package_id)) {
                            continue;
                        }
                        const entry = bun.handleOom(set.getOrPut(client.lockfile.allocator, @truncate(root_dep.name_hash)));
                        if ((!entry.found_existing)) {
                            const dependency_slice = parts.items(.dependencies)[@as(usize, @intCast(package_id))];
                            _ = addDependenciesToSet((&set), client.lockfile, dependency_slice);
                        }
                        break;
                    }
                }
            }
        }
        return set;
}

pub fn addDependenciesToSet(names: *std.AutoArrayHashMapUnmanaged(TruncatedPackageNameHash,void), lockfile: *Lockfile, dependencies_slice: Lockfile.DependencySlice) void {
        const begin = dependencies_slice.off;
        const end = (begin +| dependencies_slice.len);
        var dep_id = begin;
        _ = &dep_id;
        while ((dep_id < end)) : (dep_id = (dep_id + 1)) {
            const package_id = lockfile.buffers.resolutions.items[@as(usize, @intCast(dep_id))];
            if ((package_id == invalid_package_id)) {
                continue;
            }
            const dep = lockfile.buffers.dependencies.items[@as(usize, @intCast(dep_id))];
            const entry = bun.handleOom(names.getOrPut(lockfile.allocator, @truncate(dep.name_hash)));
            if ((!entry.found_existing)) {
                const dependency_slice = lockfile.packages.items(.dependencies)[@as(usize, @intCast(package_id))];
                _ = addDependenciesToSet(names, lockfile, dependency_slice);
            }
        }
}
